cat > facts.json <<'EOF'
[
  {
    "id": "tiktok-share-new-charting-artists",
    "source": "Of the artists who charted on Spotify from January 2020 to December 2021, 332 had never charted before. 25% of them came from TikTok.",
    "claim": "84 of the 332 artists who first charted in 2020-2021 came from TikTok, 25.3%.",
    "tables": {
      "a": "data/artists.csv",
      "c": "data/charting-artists.csv"
    },
    "code": "(c[\"Did TikTok play a role in starting this person's career?\"].eq('Yes') | c['Artist'].isin(a['name'])).agg(['count','sum','mean'])"
  },
  {
    "id": "milestones-per-viral-artist",
    "source": "Let's look at the number of milestones met by each of the 125 musicians who went viral on TikTok.",
    "claim": "The musicians met between 0 and 8 of the 8 milestones: 10 met none, 30 met 1, 27 met 2, 11 met 3, 16 met 4, 12 met 5, 11 met 6, 5 met 7 and 3 met all 8.",
    "tables": {
      "a": "data/artists.csv"
    },
    "code": "(a['signed status post-TikTok'].ne('not signed').astype(int) + a['Spotify Mo. Listen  > 1M'].eq('Yes').astype(int) + a['Played Festival'].astype(int) + a['Touring Post-Tiktok'].astype(int) + a['Post-Viral Top 200 Charted'].astype(int) + a['Post-viral Editorially Playlisted'].astype(int) + a['IG >500K'].eq('Yes').astype(int) + a['YouTube >500K'].eq('Yes').astype(int)).value_counts().sort_index()"
  }
]
EOF
cat > skipped.json <<'EOF'
[
  {
    "source": "We found about 5,000 songs that were popular on TikTok in 2020.",
    "why": "The folder has artist-level files only; there is no song-level TikTok data to count the roughly 5,000 popular songs."
  },
  {
    "source": "We needed a threshold for what's bonafide TikTok viral, so we decided on songs with at least 100,000 TikTok posts",
    "why": "The folder has no TikTok post counts or song-level records, so the 100,000-post threshold cannot be applied or checked."
  },
  {
    "source": "of the hundreds of thousands of sounds on TikTok, 1,000 songs surpassed 100,000 posts, and 12.5% of those songs were from emerging artists.",
    "why": "The 1,000-song denominator and the TikTok post counts are absent; artists.csv contains the 125 emerging artists but no count of all songs that passed 100,000 posts, so 12.5% cannot be computed."
  },
  {
    "source": "Most of the music that went viral on TikTok was from artists who were already popular, well before 2020 and even TikTok's founding.",
    "why": "This needs the full song-level viral dataset with each song's artist and pre-existing popularity; the folder contains only the 125 emerging artists and the 332 first-time charters."
  },
  {
    "source": "one of the OVER 1 MILLION videos for \"Just Did a Bad Thing.\"",
    "why": "The number of TikTok videos using the sound is not in either file."
  },
  {
    "source": "This 16-second \"song.\"",
    "why": "The song's duration is not recorded in either file."
  }
]
EOF
python3 -m json.tool facts.json >/dev/null && python3 -m json.tool skipped.json >/dev/null && echo JSON_OK

